import { createRequire } from 'module'
const require = createRequire('/home/runner/.local/share/omgithub-playwright/')
const { chromium } = require('playwright')

const browser = await chromium.launch({
  headless: false,
  args: ['--enable-gpu', '--ignore-gpu-blocklist', '--enable-unsafe-webgpu'],
})
const page = await browser.newPage({ viewport: { width: 1280, height: 800 } })
const errors = []
page.on('console', (m) => { if (m.type() === 'error') errors.push(m.text()) })
page.on('pageerror', (e) => errors.push(String(e)))
const shot = (n) => page.screenshot({ path: `/tmp/opencode/${n}.png` })
const state = () => page.evaluate(() => {
  const g = window.__NEON_APEX__
  return { screen: g.game.screen, paused: g.game.paused, drag: g.game.drag && { phase: g.game.drag.phase, gear: g.game.drag.player.gear }, drift: g.game.drift && { phase: g.game.drift.phase, timer: g.game.drift.timer, score: g.game.drift.scoreF }, save: { ...g.save } }
})
const press = async (key, wait = 140) => { await page.keyboard.press(key); await page.waitForTimeout(wait) }

await page.goto('http://localhost:3000', { waitUntil: 'networkidle' })
await page.evaluate(() => localStorage.clear())
await page.reload({ waitUntil: 'networkidle' })
await page.waitForTimeout(700)
await shot('d-title')
console.log('title', (await state()).screen)

await press('Enter', 600)
await shot('d-menu')
console.log('menu', (await state()).screen)

// Help via navigation (3 downs from item 0)
await press('ArrowDown'); await press('ArrowDown'); await press('ArrowDown')
await press('Enter', 500)
await shot('d-help')
console.log('help', (await state()).screen)

// Escape back to menu, then garage (item 2)
await press('Escape', 400)
await press('ArrowUp') // index 2
await press('Enter', 500)
await shot('d-garage')
console.log('garage', (await state()).screen)

// Back to menu, then drag
await press('Escape', 400)
await press('ArrowUp'); await press('ArrowUp') // index 0
await press('Enter', 600)
await shot('d-drag-count')
console.log('drag-count', await page.evaluate(() => window.__NEON_APEX__.game.drag?.phase))

// Wait for green, then launch and shift
await page.waitForFunction(() => window.__NEON_APEX__.game.drag?.phase === 'run', null, { timeout: 6000 })
await page.keyboard.down('ArrowUp')
let shifts = 0
for (let i = 0; i < 260; i++) {
  const st = await page.evaluate(() => {
    const d = window.__NEON_APEX__.game.drag
    return d ? { phase: d.phase, rpm: d.player.rpm, gear: d.player.gear } : null
  })
  if (!st || st.phase === 'done') break
  if (st.rpm > 6700 && st.gear < 5) { await page.keyboard.press('Space'); shifts++ }
  if (i === 45) await page.keyboard.press('n')
  await page.waitForTimeout(25)
}
await page.keyboard.up('ArrowUp')
await page.waitForTimeout(500)
await shot('d-drag-result')
console.log('drag-result', JSON.stringify(await state()), 'shifts', shifts)

// Retry via mouse
const box = await page.locator('#game').boundingBox()
const vx = (x) => box.x + x * box.width / 384
const vy = (y) => box.y + y * box.height / 216
await page.mouse.click(vx(132), vy(173))
await page.waitForTimeout(400)
console.log('after-retry', JSON.stringify(await state()))

// Pause / resume / quit
await press('p', 350)
await shot('d-pause')
console.log('paused', (await state()).paused)
await page.mouse.click(vx(192), vy(106))
await page.waitForTimeout(350)
console.log('resumed', (await state()).paused)
await press('p', 300)
await page.mouse.click(vx(192), vy(134))
await page.waitForTimeout(500)
console.log('after-quit', (await state()).screen)

// Drift mode via menu navigation
await press('ArrowDown') // drift
await press('Enter', 400)
await shot('d-drift-count')
await page.waitForFunction(() => window.__NEON_APEX__.game.drift?.phase === 'run', null, { timeout: 6000 })
await page.keyboard.down('ArrowUp')
await page.keyboard.down('Space')
let steer = 0
for (let i = 0; i < 600; i++) {
  const st = await page.evaluate(() => {
    const g = window.__NEON_APEX__
    const d = g.game.drift
    if (!d) return null
    const w = g.game.driftWorld
    const c = d.car
    if (!w) return { phase: d.phase, timer: d.timer }
    let best = 1e9, bi = 0
    for (let j = 0; j < w.samples.length; j++) {
      const s = w.samples[j]
      const dd = (c.x - s.x) ** 2 + (c.y - s.y) ** 2
      if (dd < best) { best = dd; bi = j }
    }
    const t = w.samples[(bi + 8) % w.samples.length]
    let want = Math.atan2(t.y - c.y, t.x - c.x) - c.angle
    while (want > Math.PI) want -= Math.PI * 2
    while (want < -Math.PI) want += Math.PI * 2
    return { phase: d.phase, timer: d.timer, score: d.scoreF, combo: d.combo, slip: c.slip, walls: d.walls, want, speed: c.speed }
  })
  if (!st || st.phase === 'done') break
  const want = st.want ?? 0
  const ns = want > 0.10 ? 1 : want < -0.10 ? -1 : 0
  if (ns !== steer) {
    if (steer > 0) await page.keyboard.up('ArrowRight')
    if (steer < 0) await page.keyboard.up('ArrowLeft')
    if (ns > 0) await page.keyboard.down('ArrowRight')
    if (ns < 0) await page.keyboard.down('ArrowLeft')
    steer = ns
  }
  if (i === 30) await page.keyboard.press('n')
  await page.waitForTimeout(30)
}
if (steer > 0) await page.keyboard.up('ArrowRight')
if (steer < 0) await page.keyboard.up('ArrowLeft')
await shot('d-drift-run')
console.log('drift-run', JSON.stringify(await state()))
// Force finish
await page.evaluate(() => { if (window.__NEON_APEX__.game.drift) window.__NEON_APEX__.game.drift.timer = 0.2 })
await page.waitForFunction(() => window.__NEON_APEX__.game.drift?.phase === 'done', null, { timeout: 3000 })
await page.keyboard.up('Space')
await page.keyboard.up('ArrowUp')
await page.waitForTimeout(500)
await shot('d-drift-result')
console.log('drift-result', JSON.stringify(await state()))
console.log('errors', errors)
await browser.close()

import { createRequire } from 'module'
const require = createRequire('/home/runner/.local/share/omgithub-playwright/')
const { chromium } = require('playwright')

const browser = await chromium.launch({ headless: false, args: ['--enable-gpu', '--ignore-gpu-blocklist'] })
const errors = []

async function tapV(page, x, y) {
  const b = await page.locator('#game').boundingBox()
  await page.touchscreen.tap(b.x + x * b.width / 384, b.y + y * b.height / 216)
}
const state = (page) => page.evaluate(() => {
  const g = window.__NEON_APEX__
  const d = g.game.drag
  return {
    screen: g.game.screen, paused: g.game.paused, body: document.body.className,
    drag: d && { phase: d.phase, gear: d.player.gear, rpm: d.player.rpm, dist: d.player.distance, result: d.result },
    drift: g.game.drift && { phase: g.game.drift.phase, timer: g.game.drift.timer },
    save: { ...g.save }, hits: g.game.hits.map((h) => h.id),
  }
})
const shot = (page, n) => page.screenshot({ path: `/tmp/opencode/${n}.png` })

async function run(viewport, name, isLandscape) {
  const ctx = await browser.newContext({ viewport, isMobile: true, hasTouch: true, deviceScaleFactor: 2 })
  const page = await ctx.newPage()
  page.on('console', (m) => { if (m.type() === 'error') errors.push(name + ': ' + m.text()) })
  page.on('pageerror', (e) => errors.push(name + ': ' + String(e)))
  await page.goto('http://localhost:3000', { waitUntil: 'networkidle' })
  await page.evaluate(() => localStorage.clear())
  await page.reload({ waitUntil: 'networkidle' })
  await page.waitForTimeout(800)
  await shot(page, `${name}-title`)
  console.log(name, 'title', JSON.stringify(await state(page)))

  // tap canvas to title->menu
  await tapV(page, 192, 120)
  await page.waitForTimeout(500)
  await shot(page, `${name}-menu`)
  console.log(name, 'menu', JSON.stringify(await state(page)))

  // garage = third menu row (y ~105..131 center 118)
  await tapV(page, 100, 118)
  await page.waitForTimeout(500)
  await shot(page, `${name}-garage`)
  console.log(name, 'garage', JSON.stringify(await state(page)))

  // back
  await tapV(page, 42, 190)
  await page.waitForTimeout(400)
  // drag = first row y58
  await tapV(page, 100, 58)
  await page.waitForTimeout(600)
  await shot(page, `${name}-drag-count`)
  console.log(name, 'drag count', JSON.stringify(await state(page)))

  // touch buttons and drag race
  const gas = page.locator('[data-act="throttle"]')
  const shift = page.locator('[data-act="shift"]')
  const nitro = page.locator('[data-act="nitro"]')
  const gb = await gas.boundingBox()
  const sb = await shift.boundingBox()
  const nb = await nitro.boundingBox()
  console.log(name, 'buttons', { gas: gb, shift: sb, nitro: nb })

  // wait green then hold gas with touchscreen (CDP raw touches so multi-touch works)
  await page.waitForFunction(() => window.__NEON_APEX__.game.drag?.phase === 'run', null, { timeout: 6000 })
  const cdp = await ctx.newCDPSession(page)
  const pt = (x, y, id) => ({ x, y, id })
  const gc = pt(gb.x + gb.width / 2, gb.y + gb.height / 2, 1)
  const sc = pt(sb.x + sb.width / 2, sb.y + sb.height / 2, 2)
  const nc = pt(nb.x + nb.width / 2, nb.y + nb.height / 2, 3)
  const dispatch = (type, pts) => cdp.send('Input.dispatchTouchEvent', { type, touchPoints: pts })
  await dispatch('touchStart', [gc])
  let shifts = 0
  for (let i = 0; i < 300; i++) {
    const st = await page.evaluate(() => {
      const d = window.__NEON_APEX__.game.drag
      return d ? { phase: d.phase, rpm: d.player.rpm, gear: d.player.gear } : null
    })
    if (!st || st.phase === 'done') break
    if (st.rpm > 6700 && st.gear < 5) {
      await dispatch('touchStart', [gc, sc])
      await page.waitForTimeout(40)
      await dispatch('touchEnd', [sc])
      shifts++
    }
    if (i === 40) { await dispatch('touchStart', [gc, nc]); await page.waitForTimeout(50); await dispatch('touchEnd', [nc]) }
    await page.waitForTimeout(30)
  }
  await dispatch('touchEnd', [gc])
  await page.waitForTimeout(500)
  await shot(page, `${name}-drag-result`)
  console.log(name, 'drag result', JSON.stringify(await state(page)), 'shifts', shifts)

  // tap retry center (132,173)
  await tapV(page, 132, 173)
  await page.waitForTimeout(400)
  console.log(name, 'after retry', JSON.stringify(await state(page)))
  await page.waitForFunction(() => window.__NEON_APEX__.game.drag?.phase === 'run', null, { timeout: 6000 })

  // pause via fixed button, resume via canvas
  const pb = await page.locator('#pauseBtn').boundingBox()
  await page.touchscreen.tap(pb.x + pb.width / 2, pb.y + pb.height / 2)
  await page.waitForTimeout(400)
  await shot(page, `${name}-pause`)
  console.log(name, 'paused', JSON.stringify(await state(page)))
  await tapV(page, 192, 106)
  await page.waitForTimeout(400)
  console.log(name, 'resumed', JSON.stringify(await state(page)))

  // pause again and quit
  await page.touchscreen.tap(pb.x + pb.width / 2, pb.y + pb.height / 2)
  await page.waitForTimeout(300)
  await tapV(page, 192, 134)
  await page.waitForTimeout(500)
  console.log(name, 'quit', JSON.stringify(await state(page)))

  // drift
  await tapV(page, 100, 88)
  await page.waitForTimeout(500)
  await shot(page, `${name}-drift-count`)
  await page.waitForTimeout(3600)
  await shot(page, `${name}-drift-run`)
  console.log(name, 'drift', JSON.stringify(await state(page)))
  // force finish and check result
  await page.evaluate(() => { const d = window.__NEON_APEX__.game.drift; if (d) d.timer = 0.2 })
  await page.waitForTimeout(600)
  await shot(page, `${name}-drift-result`)
  console.log(name, 'drift result', JSON.stringify(await state(page)))
  await ctx.close()
}

await run({ width: 390, height: 844 }, 'm-portrait', false)
await run({ width: 844, height: 390 }, 'm-landscape', true)
console.log('errors', errors)
await browser.close()

